--- index.html
+++ index.html
@@ -65,9 +65,9 @@
 function choose(){if(mode==='command'){resolve(['fight','act','item','mercy'][selection]);return}if(mode==='fight'){let phase=(frame%100)/100;let power=1-Math.min(1,Math.abs(phase-.5)*2);let damage=power>.82?4:power>.55?2:1;enemyMood+=damage>=2?1:0;setLine(damage>=4?'A perfect strike! Moth wobbles, but is still smiling.':damage===2?'You land a careful hit. Moth nods bravely.':'Your swing barely brushes the cloak.');hint.textContent=`Moth's resolve: ${Math.min(enemyMood,3)}/3`;setMode('command');selection=1;syncButtons();setTimeout(()=>{if(mode==='command')enemyTurn()},1200);return}if(mode==='act'){const lines=['You ask about the lantern. “It remembers the way home,” Moth says.','You compliment the patchwork cloak. Moth beams and stands a little taller.','You sit quietly together. The silence feels warm, not awkward.'];setLine(lines[actMenu]);enemyMood++;selection=1;setMode('command');syncButtons();hint.textContent=`Moth's shyness eases · ${Math.min(enemyMood,3)}/3`;setTimeout(()=>{if(mode==='command')enemyTurn()},1450);return}if(mode==='item'){if(turn===0){hp=Math.min(20,hp+7);setHp();turn=1;setLine('You eat the Starberry. It tastes like a summer evening. (+7 HP)');hint.textContent='Starberry used.';setMode('command');selection=2;syncButtons();setTimeout(()=>{if(mode==='command')enemyTurn()},1200)}else{setLine('Nothing left in your pockets but lint.');hint.textContent='Empty pockets.'}return}if(mode==='mercy'){if(enemyMood>=2){setMode('ending');ending='spared';setLine('You offer a hand. Moth takes it, and the lantern glows.');hint.textContent='A peaceful ending · press Z to play again';}else{setLine('Moth hesitates. “Could you stay a little longer?”');hint.textContent='Try a kind ACT first.';setMode('command');selection=1;syncButtons()}return}if(mode==='ending'){if(ending==='down'){hp=20;setHp();enemyMood=0;turn=0;setMode('command');selection=0;syncButtons();setLine('A small figure blocks the path. The lantern flickers.')}else{hp=20;setHp();enemyMood=0;turn=0;ending='';setMode('command');selection=0;syncButtons();setLine('A new journey begins beneath the world.')}hint.textContent='Choose what Rowan does.'}}
 function syncButtons(){opts.forEach((b,i)=>b.classList.toggle('selected',i===selection))}
 function back(){if(['act','item','mercy'].includes(mode)){setMode('command');setLine('A small figure waits patiently.');hint.textContent='Choose what Rowan does.'}else if(mode==='fight'){setMode('command');setLine('You lower your guard.');}}
 function move(dx,dy){if(mode!=='dodge')return;heart.x=Math.max(235,Math.min(725,heart.x+dx));heart.y=Math.max(302,Math.min(406,heart.y+dy))}
-function key(e){const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(mode==='intro'){if(k==='z'||k==='enter'||k===' '){start()}return}if(mode==='dodge'){if(k==='arrowleft'||k==='a')move(-18,0);if(k==='arrowright'||k==='d')move(18,0);if(k==='arrowup'||k==='w')move(0,-18);if(k==='arrowdown'||k==='s')move(0,18);return}if(k==='escape'||k==='x'){back();return}if(mode==='command'){if(k==='arrowleft'||k==='a'){selection=(selection+3)%4;syncButtons()}if(k==='arrowright'||k==='d'){selection=(selection+1)%4;syncButtons()}if(k==='z'||k==='enter'||k===' '){choose()}return}if(mode==='act'&&(k==='arrowup'||k==='arrowdown'||k==='w'||k==='s')){actMenu=(actMenu+(k==='arrowup'||k==='w'?2:1))%3;setLine(['Ask about the lantern','Compliment the cloak','Wait in silence'][actMenu]);return}if(k==='z'||k==='enter'||k===' '){choose()}}
+function key(e){const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' ','enter'].includes(k))e.preventDefault();if(mode==='intro'){if(k==='z'||k==='enter'||k===' '){start()}return}if(mode==='dodge'){if(k==='arrowleft'||k==='a')move(-18,0);if(k==='arrowright'||k==='d')move(18,0);if(k==='arrowup'||k==='w')move(0,-18);if(k==='arrowdown'||k==='s')move(0,18);return}if(k==='escape'||k==='x'){back();return}if(mode==='command'){if(k==='arrowleft'||k==='a'){selection=(selection+3)%4;syncButtons()}if(k==='arrowright'||k==='d'){selection=(selection+1)%4;syncButtons()}if(k==='z'||k==='enter'||k===' '){choose()}return}if(mode==='act'&&(k==='arrowup'||k==='arrowdown'||k==='w'||k==='s')){actMenu=(actMenu+(k==='arrowup'||k==='w'?2:1))%3;setLine(['Ask about the lantern','Compliment the cloak','Wait in silence'][actMenu]);return}if(k==='z'||k==='enter'||k===' '){choose()}}
 window.addEventListener('keydown',key);document.getElementById('begin').addEventListener('click',start);opts.forEach((b,i)=>{b.addEventListener('click',()=>{selection=i;syncButtons();if(mode==='command')resolve(b.dataset.action);else choose()})});document.querySelectorAll('.mobile-controls button').forEach(b=>{const dir=b.dataset.dir;let dx=0,dy=0;if(dir==='left')dx=-18;if(dir==='right')dx=18;if(dir==='up')dy=-18;if(dir==='down')dy=18;b.addEventListener('pointerdown',e=>{e.preventDefault();move(dx,dy)})});
 // Collision/update and periodic hazards
 const originalDraw=draw;
 function animate(){requestAnimationFrame(animate);if(mode==='dodge'){for(const b of bullets){b.x+=b.vx;b.y+=b.vy;b.r=b.type==='petal'?7:6;if(Math.hypot(b.x-heart.x,b.y-heart.y)<14){takeDamage();b.x=-999}}bullets=bullets.filter(b=>b.x>205&&b.x<755&&b.y>265&&b.y<444);if(invuln>0)invuln--}originalDraw()}
